// Extract and prepare debate data for analysis
const root = $input.first().json;
const debateData = root.debateData || (root.body && root.body.debateData);
const messages = debateData.messages || [];
const config = debateData.config || {};
const participants = debateData.participants || [];

// Identify participants
const forParticipant = participants.find(p => p.side === 'FOR') || { name: 'Proponent', id: 'for_user' };
const againstParticipant = participants.find(p => p.side === 'AGAINST') || { name: 'Opponent', id: 'against_user' };

// Separate messages
const forMessages = messages.filter(msg => msg.side === 'FOR');
const againstMessages = messages.filter(msg => msg.side === 'AGAINST');

// Calculate basic metrics
const totalMessages = messages.length;
const forMessageCount = forMessages.length;
const againstMessageCount = againstMessages.length;

// Prepare conversation transcript
const conversationTranscript = messages
  .sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp))
  .map(msg => {
    const speakerName = msg.senderName || (msg.side === 'FOR' ? forParticipant.name : againstParticipant.name);
    const side = msg.side || 'UNKNOWN';
    const timestamp = new Date(msg.timestamp).toISOString();
    return `[${timestamp}] ${speakerName} (${side}): ${msg.text}`;
  })
  .join('\n\n');

// Extract debate context
const debateContext = {
  topic: config.topic || 'Unknown Topic',
  forSpeaker: forParticipant.name,
  againstSpeaker: againstParticipant.name,
  duration: debateData.duration || 0,
  roomId: debateData.roomId || null
};

// Prepare structured data for Gemini analysis
const analysisInput = {
  conversationTranscript,
  debateContext,
  metrics: {
    totalMessages,
    forMessageCount,
    againstMessageCount,
    conversationLength: conversationTranscript.length
  },
  participants: {
    for: forParticipant,
    against: againstParticipant
  },
  rawData: debateData
};

return [{ json: analysisInput }];

