// Enhanced Analysis Result Processor for Direct Gemini HTTP API
const requestStartTime = Date.now();

try {
  const data = $input.first().json || $input.first();

  // Extract Gemini response from HTTP API format
  const geminiText = data.candidates?.[0]?.content?.parts?.[0]?.text || '';

  let analysisResult;

  if (geminiText) {
    try {
      // Try to parse the JSON response directly
      analysisResult = JSON.parse(geminiText.trim());

      // Validate that we have the required structure
      if (!analysisResult.winner || !analysisResult.forAnalysis || !analysisResult.againstAnalysis) {
        throw new Error('Invalid analysis structure');
      }

    } catch (parseError) {
      console.error('Failed to parse Gemini JSON response:', parseError);

      // Try to extract JSON from markdown code blocks if present
      const jsonMatch = geminiText.match(/```json\n([\s\S]*?)\n```/) || 
                       geminiText.match(/\{[\s\S]*\}/);

      if (jsonMatch) {
        try {
          const jsonString = jsonMatch[1] || jsonMatch[0];
          analysisResult = JSON.parse(jsonString);
        } catch (secondParseError) {
          throw new Error('Could not parse extracted JSON');
        }
      } else {
        throw new Error('No valid JSON found in response');
      }
    }
  } else {
    throw new Error('No response text from Gemini');
  }

} catch (error) {
  console.error('Failed to process Gemini response:', error);

  // Fallback analysis structure
  analysisResult = {
    winner: "DRAW",
    winningReason: "Analysis unavailable due to technical error.",
    forAnalysis: {
      overallScore: 70,
      performanceMetrics: { argumentation: { score: 70, strengths: [], weaknesses: [], improvement: "" } },
      keyStrengths: [],
      areasForImprovement: [],
      specificFeedback: {}
    },
    againstAnalysis: {
      overallScore: 70,
      performanceMetrics: { argumentation: { score: 70, strengths: [], weaknesses: [], improvement: "" } },
      keyStrengths: [],
      areasForImprovement: [],
      specificFeedback: {}
    },
    metadata: {
      error: error.message,
      fallbackUsed: true
    }
  };
}

// Add comprehensive metadata
analysisResult.metadata = {
  ...analysisResult.metadata,
  analysisDate: new Date().toISOString(),
  model: 'gemini-2.0-flash-exp',
  version: '2.0',
  processingTime: Date.now() - requestStartTime,
  responseSource: 'direct-http-api'
};

return [{ json: analysisResult }];
